		haveKubeCreds     bool
		tunnel            reversetunnel.Server
		kubeServices      []services.Server

		wantCtx *authContext
		wantErr bool
	}{
		{
			desc:           "local user and cluster",
			user:           auth.LocalUser{},
			roleKubeGroups: []string{"kube-group-a", "kube-group-b"},
